            if( turnstileLoaded ){
                initTurnstile();
            } else {
                $( window ).on( 'turnstileLoaded', function() {
                    turnstileLoaded = true;
                    initTurnstile();
                });
            }
        };

		ips.ui.registerWidget( 'captcha', ips.ui.captcha, [
			'service', 'key', 'lang', 'theme'
