								newRange.setEndAfter(text);
								selection.addRange(newRange);

								// now see if we need to truncate
								if (label.innerText.trim().length > 30) {
									let precedingTextLength = 0;
									for (let node of label.childNodes) {
										if (node === text) {
											break;
										}
										if (node instanceof Text) {
