						textColor = typeof l === "number" ? (l < 0.6 ? "#fff" : "#000") : initialColor;
					}

					input.closest('.ipsInput__color-wrap')?.style.setProperty("--i-co-inverse", textColor);
					input.closest('.ipsInput__color-wrap')?.style.setProperty("--i-co", `${input.value}`);
