		deleteComment: function (e) {
			e.preventDefault();

			var url = $( e.currentTarget ).attr('href');
			var commentData = this._getQuoteData();

			var eventData = Object.assign( commentData, {
				url: url,
				commentID: this._commentID
			});

			ips.ui.alert.show( {
				type: 'confirm',
				icon: 'warn',
				message: ips.getString('delete_confirm'),
				callbacks: {
