					if (!submit.length) {
						return;
					}


					/**
					 * Recursively check to see if a node has actual content
					 * @param	node		A node in the Prose Mirror Document Tree
					 * @return {boolean}
					 */
					function nodeHasContent(node) {
						if (node.textContent?.trim()?.length) {
							return true;
						}

						if (node.isAtom && !node.isText) {
