                (atEnd ? 0 : index + (dir === 'prev' ? -1 : 1))) % total;

            const childBox = children[toIndex].getBoundingClientRect();
            const paddedBox = this.getPaddedScrollBox();
            let scrollAmount;
            if (this.isRTL()) {
                scrollAmount = (toIndex === total - 1 ? childBox.left : childBox.right) - paddedBox.right;
