                this.elem.ipsHide();
                return;
            }

            this.elem.ipsShow();

            const buttonContainer = this.elem;
            buttonContainer.querySelectorAll('[data-carousel-arrow]').forEach(button => button.addEventListener('click', e => this.carouselScroll(e)));
