			if( options.manageable ){
				_setUpManageable();
			}

			if( options.sortable ){
				ips.loader.get( ['core/interface/jquery/jquery-ui.js'] ).then( function () {
					elem.find('tbody').sortable( {
						handle: '.ipsTree_drag'
					});
				});
			}

			_checkRows();
		},

		/**
		 * Sets up the various events the matrix needs
		 *
		 * @returns {void}
